seed_translations(slug, locale, title, excerpt, body, seo_title, seo_description) as (
  values
    ('chon-dien-tich-kho-mini','vi','Chọn diện tích kho mini: bắt đầu từ đồ cần lưu, không bắt đầu từ số m²','Một cách thực tế để ước lượng kho: lập danh sách đồ, đo phần chiếm chỗ, tính khả năng xếp theo chiều cao và chừa lối tiếp cận trước khi nhìn bảng diện tích.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Câu hỏi “cần kho bao nhiêu mét vuông?” thường xuất hiện quá sớm. Nếu bắt đầu từ một con số diện tích, người thuê dễ rơi vào hai cực: chọn quá nhỏ vì chỉ tính phần sàn đang bị đồ chiếm, hoặc chọn quá lớn vì muốn “chắc chắn đủ”. Cách tốt hơn là bắt đầu từ những gì thực sự cần lưu và cách bạn sẽ lấy chúng ra trong suốt thời gian thuê."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Lập danh sách theo nhóm, không cần liệt kê từng món"}]},{"type":"paragraph","content":[{"type":"text","text":"Hãy chia đồ thành các nhóm có hành vi lưu trữ giống nhau: thùng carton có thể xếp chồng, kệ/hộp nhựa, hàng dễ vỡ, đồ cồng kềnh, vật dụng cần lấy thường xuyên và nhóm lưu dài hạn. Với shop online, có thể thay nhóm đồ bằng nhóm SKU hoặc thùng hàng. Mục tiêu của bước này là biết loại không gian nào bạn đang tạo ra, chứ chưa phải tính diện tích chính xác."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Đếm số thùng hoặc kiện tương đối đồng kích thước."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Đo riêng các món cồng kềnh không thể xếp chồng."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Đánh dấu nhóm cần lấy thường xuyên để dành lối tiếp cận."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tách đồ dễ vỡ hoặc không chịu lực khỏi nhóm có thể chồng cao."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Phân biệt diện tích chiếm sàn và thể tích có thể tận dụng"}]},{"type":"paragraph","content":[{"type":"text","text":"Một kho có cùng diện tích sàn có thể chứa rất khác nhau tùy cách xếp. Nếu các thùng đồng cỡ, chắc chắn và có thể chồng, chiều cao giúp giảm phần sàn cần dùng. Ngược lại, hàng dễ vỡ, hình dạng bất quy tắc hoặc cần lấy từng món thường xuyên sẽ cần nhiều diện tích sàn và khoảng trống thao tác hơn. Vì vậy, đừng chuyển số thùng trực tiếp thành số m² nếu chưa nghĩ đến cách xếp."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Lối đi là một phần của thiết kế kho, không phải diện tích thừa"}]},{"type":"paragraph","content":[{"type":"text","text":"Nếu mục tiêu là lưu dài hạn và hầu như không mở kho, bạn có thể xếp dày hơn. Nếu dùng kho như một điểm lấy hàng hàng tuần, lối đi và mặt kệ dễ tiếp cận trở thành phần bắt buộc. Một kho “đủ chỗ để đóng cửa” chưa chắc là một kho vận hành được."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Nguyên tắc thực tế: diện tích phù hợp là diện tích giúp bạn vừa chứa được đồ vừa thực hiện được hành vi bạn cần — lấy, kiểm, bổ sung hoặc di chuyển."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Chừa biên tăng trưởng có chủ đích"}]},{"type":"paragraph","content":[{"type":"text","text":"Shop online hoặc doanh nghiệp nhỏ thường có tồn kho biến động. Thay vì thuê dư rất nhiều để phòng xa, hãy xác định mức tăng hợp lý trong vài chu kỳ nhập hàng tới và hỏi xem phương án nâng hoặc đổi loại kho có linh hoạt hay không. Với nhu cầu cá nhân, biên dự phòng có thể nhỏ hơn nếu danh sách đồ đã chốt."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Checklist trước khi hỏi NupsBox"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tổng số thùng/kiện và kích thước phổ biến."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kích thước món lớn nhất."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nhóm nào có thể xếp chồng; nhóm nào không."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tần suất bạn dự kiến vào kho."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bạn cần lối đi đến tất cả đồ hay chỉ một số nhóm."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Khả năng lượng hàng tăng trong thời gian thuê."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Kết luận"}]},{"type":"paragraph","content":[{"type":"text","text":"Đừng chọn kho chỉ vì một nhãn S/M/L hoặc một con số m². Hãy mô tả đồ, cách xếp và cách sử dụng trước. Sau đó mới đối chiếu với loại kho đang có trong catalog NupsBox và xác nhận tình trạng thực tế. Cách này giúp cuộc trao đổi ngắn hơn, dễ so sánh hơn và giảm rủi ro thuê thiếu hoặc thuê dư."}]}]}'::jsonb,'Cách chọn diện tích kho mini phù hợp | NupsBox','Hướng dẫn ước lượng diện tích kho mini từ số thùng, đồ cồng kềnh, khả năng xếp chồng và nhu cầu lấy đồ thay vì đoán theo cảm giác.'),
    ('chon-dien-tich-kho-mini','en','Choosing mini-storage size: start with what you store, not a square-metre number','A practical sizing method: list what you store, measure bulky footprints, consider vertical stacking and preserve the access path before comparing unit sizes.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The question “how many square metres do I need?” often comes too early. Starting with a floor-area number pushes people toward two mistakes: choosing too small because they only count today’s footprint, or choosing too large because extra space feels safer. A better approach starts with what will be stored and how you need to retrieve it during the rental period."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Group items by storage behaviour"}]},{"type":"paragraph","content":[{"type":"text","text":"You do not need an item-by-item spreadsheet. Group belongings or inventory into stackable cartons, bins, fragile goods, bulky items, frequently accessed items and long-term items. Online sellers can use SKU families or carton types. The point is to understand the kind of space you need before translating it into an area."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Count cartons or cases of roughly similar size."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Measure bulky pieces that cannot be stacked."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark the groups you will retrieve frequently."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Separate fragile or non-load-bearing goods from stackable stock."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Separate floor footprint from usable volume"}]},{"type":"paragraph","content":[{"type":"text","text":"Two units with the same floor area can hold very different quantities depending on stacking. Uniform, strong cartons can use vertical space efficiently. Fragile, irregular or frequently accessed goods need more floor area and handling space. Do not convert carton count directly into square metres before thinking through the stacking pattern."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. An access aisle is part of the design"}]},{"type":"paragraph","content":[{"type":"text","text":"For long-term storage with almost no retrieval, dense packing can make sense. If the unit supports weekly order picking or regular access, aisles and reachable faces become part of the requirement. A unit that can physically close is not necessarily a unit you can operate efficiently."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"A suitable unit is one that supports both storage and the actions you need to perform: retrieve, check, replenish and move."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Leave intentional growth capacity"}]},{"type":"paragraph","content":[{"type":"text","text":"Online sellers and small businesses often have variable stock. Instead of over-renting for an undefined future, estimate reasonable growth over the next few replenishment cycles and ask how flexible it is to change unit type later. Personal-storage needs may require less buffer when the item list is already fixed."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Checklist before contacting NupsBox"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Total cartons/cases and common dimensions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dimensions of the largest item."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What can and cannot be stacked."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Expected access frequency."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Whether every item needs direct access."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Likely inventory growth during the rental period."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"Do not choose storage only from an S/M/L label or a square-metre figure. Describe the goods, stacking pattern and access behaviour first. Then compare that requirement with the NupsBox catalog and confirm current availability. This makes the conversation faster and reduces the risk of renting too little or too much."}]}]}'::jsonb,'How to choose mini-storage size | NupsBox','Estimate mini-storage size from cartons, bulky items, stacking potential and access needs instead of guessing by square metres.'),
    ('sap-xep-kho-shop-online','vi','Sắp xếp kho cho shop online: biến một kho nhỏ thành điểm picking gọn','Cách chia vùng hàng nhanh/chậm, đặt mã kệ-bin, thiết kế lối lấy hàng và kiểm tồn để kho nhỏ không trở thành một căn phòng chất thùng.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shop online thường gặp một nghịch lý: khi số đơn tăng, kho không nhất thiết thiếu diện tích trước — nó thiếu cấu trúc trước. Hàng vẫn “còn chỗ”, nhưng thời gian tìm SKU, lấy nhầm biến thể, mở thùng và dịch chuyển vật cản bắt đầu ăn vào thời gian xử lý đơn."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Kho nhỏ nên được thiết kế quanh luồng lấy hàng"}]},{"type":"paragraph","content":[{"type":"text","text":"Hãy hình dung mỗi đơn hàng là một hành trình. SKU bán nhanh nên nằm gần lối vào hoặc trên các vị trí dễ thao tác. SKU chậm hơn có thể lùi ra phía sau hoặc lên tầng kệ cao hơn. Mục tiêu là giảm số bước và số lần phải di chuyển hàng khác để lấy món cần thiết."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Đặt mã vị trí đơn giản nhưng nhất quán"}]},{"type":"paragraph","content":[{"type":"text","text":"Shopify khuyến nghị tên bin có định dạng nhất quán, ví dụ dùng số có thêm số 0 ở đầu để sắp xếp đúng thứ tự. Bạn không cần hệ thống phức tạp: A-01, A-02, B-01 đã tốt hơn rất nhiều so với “kệ bên trái, thùng xanh”."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Một mã vị trí phải chỉ đến một chỗ có thể tìm lại nhanh."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tên kệ/bin nên đọc được theo cùng một quy luật."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dán mã ở vị trí nhìn thấy trước khi phải dịch chuyển hàng."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bản ghi tồn kho và vị trí vật lý phải dùng cùng mã."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tách vùng picking và vùng reserve"}]},{"type":"paragraph","content":[{"type":"text","text":"Nếu cùng một SKU có nhiều thùng, không nhất thiết đặt tất cả ở vị trí đẹp nhất. Giữ một lượng vừa đủ tại vùng picking và phần còn lại ở vùng reserve. Khi picking gần hết, bổ sung từ reserve. Cách này giúp vị trí dễ lấy không bị chiếm bởi lượng tồn không cần đụng đến trong ngày."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hàng bán nhanh không nên bị hàng bán chậm chặn đường"}]},{"type":"paragraph","content":[{"type":"text","text":"Khi mỗi lần lấy SKU A đều phải bê hai thùng SKU C ra ngoài, kho đã bị thiết kế ngược với nhịp bán. Hãy định kỳ xem lại nhóm hàng nhanh/chậm và đổi vị trí nếu hành vi bán thay đổi."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Một quy trình kiểm kho nhỏ nhưng đều"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kiểm một phần kho theo lịch thay vì chờ kiểm toàn bộ."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Xử lý ngay các vị trí có tồn thực tế khác hệ thống."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loại bỏ bao bì rỗng và vật cản khỏi lối picking."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ghi lại SKU thường xuyên hết chỗ hoặc phải bổ sung quá nhiều."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Khi áp dụng với kho NupsBox"}]},{"type":"paragraph","content":[{"type":"text","text":"Trước khi thuê, hãy ước lượng số kệ/thùng và chiều rộng lối thao tác bạn cần. Một kho phù hợp cho shop online không chỉ là nơi chứa được hàng; nó phải cho phép bạn tìm, lấy và bổ sung hàng với ít thao tác thừa. Khi trao đổi với NupsBox, mô tả cả số SKU và tần suất lấy hàng sẽ hữu ích hơn chỉ nói tổng số thùng."}]}]}'::jsonb,'Cách sắp xếp kho cho shop online | NupsBox','Hướng dẫn tổ chức kho nhỏ cho shop online bằng mã bin, vùng hàng nhanh/chậm, tuyến picking và quy tắc bổ sung hàng.'),
    ('sap-xep-kho-shop-online','en','Organizing storage for online sellers: make a small unit work like a picking point','Use fast/slow zones, consistent shelf-bin codes, short picking paths and lightweight cycle checks so a small unit does not become a room full of boxes.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Online sellers often hit a counterintuitive problem: as orders grow, storage may run out of structure before it runs out of physical space. There is still room for more cartons, but SKU search time, wrong-variant picks and moving obstructing boxes begin to slow fulfillment."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Design the unit around the picking flow"}]},{"type":"paragraph","content":[{"type":"text","text":"Think of each order as a route. Fast-moving SKUs belong near the entrance or in easy handling positions. Slower products can move farther back or higher on shelving. The objective is to reduce steps and reduce how often other stock must be moved before you can reach the required item."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Use simple, consistent location codes"}]},{"type":"paragraph","content":[{"type":"text","text":"Shopify recommends consistent bin naming formats, including leading zeros so locations sort predictably. You do not need a complex warehouse system: A-01, A-02 and B-01 are already much more reliable than “left shelf, blue box.”"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each location code should point to a place staff can find quickly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shelf/bin names should follow one naming rule."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Labels should be visible before stock needs to be moved."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Digital records and physical labels should use the same code."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Separate pick face from reserve stock"}]},{"type":"paragraph","content":[{"type":"text","text":"If one SKU occupies several cartons, the best access position does not need to hold all of them. Keep a working quantity in the picking zone and move the balance to reserve. Replenish the pick face as required. This preserves valuable access space for stock that is touched every day."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Do not let slow movers block fast movers"}]},{"type":"paragraph","content":[{"type":"text","text":"If every pick of SKU A requires moving two cartons of SKU C, the layout is working against your sales pattern. Review velocity periodically and change positions when demand changes."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Use small, regular inventory checks"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Count part of the unit on a schedule instead of waiting for a full stocktake."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigate location mismatches as soon as they appear."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Remove empty packaging and obstacles from picking paths."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Track SKUs that repeatedly run out of location capacity."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Applying this to NupsBox"}]},{"type":"paragraph","content":[{"type":"text","text":"Before choosing a unit, estimate shelving/carton count and the aisle width you need for handling. Good storage for an online seller is not only a space that fits inventory; it is a space that lets you find, pick and replenish with fewer wasted movements. When you contact NupsBox, describing SKU count and retrieval frequency is more useful than carton count alone."}]}]}'::jsonb,'How to organize storage for online sellers | NupsBox','Organize small online-seller storage with bin codes, velocity zones, picking paths and replenishment rules.'),
    ('kho-cho-shop-online-tu-nha-ra-kho-rieng','vi','Shop online: khi nào nên tách hàng khỏi nhà và chuyển sang kho riêng?','Không phải cứ nhiều thùng là cần thuê kho. Dấu hiệu quan trọng hơn là hàng bắt đầu làm chậm picking, làm rối không gian sống và khiến bạn mất kiểm soát tồn.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nhiều shop online khởi đầu từ một góc phòng, rồi lan sang hành lang, phòng ngủ và cuối cùng là mọi khoảng trống còn lại. Chuyển sang kho riêng không nên chỉ dựa vào cảm giác “nhà chật”. Quyết định tốt hơn dựa trên việc không gian hiện tại có còn hỗ trợ hoạt động bán hàng hay đã bắt đầu cản trở nó."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Dấu hiệu 1: tìm hàng mất nhiều thời gian hơn đóng gói"}]},{"type":"paragraph","content":[{"type":"text","text":"Khi mỗi đơn yêu cầu mở nhiều thùng hoặc di chuyển hàng khác để tìm đúng SKU, chi phí thật không nằm ở diện tích mà ở thời gian xử lý. Nếu tình trạng này lặp lại mỗi ngày, tách hàng sang một không gian được tổ chức có thể tạo giá trị vận hành rõ hơn."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Dấu hiệu 2: số tồn trên hệ thống và số thực tế bắt đầu lệch"}]},{"type":"paragraph","content":[{"type":"text","text":"Không gian quá chật khiến hàng bị đổi chỗ ngẫu nhiên, thùng mới đặt lên thùng cũ và hàng trả về không có vị trí cố định. Inventory management chỉ hiệu quả khi dữ liệu và vị trí vật lý đủ kỷ luật để đối chiếu."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Dấu hiệu 3: nhà ở trở thành khu vực vận hành"}]},{"type":"paragraph","content":[{"type":"text","text":"Nếu khu sinh hoạt phải nhường chỗ cho đóng gói, hàng nhập và vật tư vận chuyển, bạn đang dùng một tài sản có mục đích sinh hoạt cho hoạt động logistics. Tách không gian giúp ranh giới công việc – cuộc sống rõ hơn và làm quy trình dễ tiêu chuẩn hóa hơn."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Dấu hiệu 4: cao điểm theo mùa tạo ra các đợt “vỡ kho”"}]},{"type":"paragraph","content":[{"type":"text","text":"Một shop có mức tồn bình thường gọn gàng vẫn có thể mất kiểm soát khi nhập hàng trước đợt sale hoặc mùa cao điểm. Nếu biến động này lặp lại, hãy xem nó như một đặc điểm của mô hình kinh doanh chứ không phải sự cố tạm thời."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Đừng chuyển kho trước khi chuẩn hóa cách quản lý tồn"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dùng mã SKU rõ và nhất quán."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phân biệt tồn bán được, hàng lỗi/hỏng và hàng chờ xử lý."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Có vị trí nhận hàng mới trước khi đưa lên kệ."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Xác định SKU bán nhanh để bố trí gần vùng picking."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Một cách thử ít rủi ro"}]},{"type":"paragraph","content":[{"type":"text","text":"Thay vì thuê ngay một kho lớn, hãy bắt đầu bằng danh sách hàng hiện có, nhịp nhập – xuất và phần không gian bạn thực sự muốn giải phóng. Đối chiếu với loại kho nhỏ phù hợp và xem liệu việc tách một phần tồn kho đã đủ cải thiện vận hành chưa. NupsBox có thể dùng các thông tin đó để giúp bạn xác định điểm bắt đầu hợp lý hơn."}]}]}'::jsonb,'Khi nào shop online nên thuê kho riêng? | NupsBox','Các dấu hiệu cho thấy shop online nên tách hàng khỏi nhà: picking chậm, tồn khó kiểm soát, không gian sống bị chiếm và nhu cầu tăng theo mùa.'),
    ('kho-cho-shop-online-tu-nha-ra-kho-rieng','en','Online sellers: when should inventory move out of the home into dedicated storage?','A pile of boxes is not the only signal. More important signs are slower picking, weaker inventory control and a living space that has turned into an operating area.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Many online shops start in one corner of a room, expand into a hallway and eventually occupy every available gap. Moving into dedicated storage should not be based only on the feeling that the home is crowded. A better decision asks whether the current space still supports selling or has begun to obstruct it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Signal 1: finding stock takes longer than packing"}]},{"type":"paragraph","content":[{"type":"text","text":"When every order requires opening several cartons or moving other products to find the right SKU, the real cost is no longer floor area; it is processing time. If this repeats every day, separating inventory into an organized space can create meaningful operating value."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Signal 2: system stock and physical stock start drifting apart"}]},{"type":"paragraph","content":[{"type":"text","text":"Overcrowded space encourages random relocation, new cartons on top of old stock and returns without a fixed home. Inventory management only works when digital records and physical locations are disciplined enough to reconcile."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Signal 3: the home has become an operations floor"}]},{"type":"paragraph","content":[{"type":"text","text":"If living areas are used for packing, inbound stock and shipping supplies, a residential asset is doing logistics work. Separating storage creates clearer work-life boundaries and makes the operating process easier to standardize."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Signal 4: seasonal peaks repeatedly break the layout"}]},{"type":"paragraph","content":[{"type":"text","text":"A shop can look organized at normal stock levels and still collapse during pre-sale replenishment or seasonal peaks. If the same pattern repeats, treat it as part of the business model rather than a temporary incident."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Standardize inventory before you move"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use clear and consistent SKU codes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Separate sellable stock, damaged stock and pending returns."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create an inbound holding position before stock reaches shelving."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Identify fast movers so they can sit near the picking zone."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A lower-risk way to test the change"}]},{"type":"paragraph","content":[{"type":"text","text":"Instead of jumping into a large warehouse, start with your current inventory list, inbound/outbound rhythm and the exact home area you want to reclaim. Compare that with a smaller unit and test whether separating only part of the stock improves operations. NupsBox can use those inputs to help identify a more practical starting point."}]}]}'::jsonb,'When should an online seller use dedicated storage? | NupsBox','Signs it may be time to move online-shop stock out of the home: slow picking, inventory mismatch, lost living space and seasonal stock peaks.'),
    ('kho-hay-mo-rong-van-phong','vi','Doanh nghiệp nhỏ: nên thuê thêm văn phòng hay tách riêng kho?','Nếu vấn đề chính là hàng mẫu, vật tư và tồn kho chiếm chỗ, mở rộng văn phòng có thể là cách giải quyết đắt tiền cho sai bài toán.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Một văn phòng bắt đầu chật không có nghĩa là doanh nghiệp luôn cần văn phòng lớn hơn. Trước khi mở rộng, hãy hỏi diện tích đang thiếu được dùng cho công việc tạo giá trị gì: chỗ ngồi, phòng họp, tiếp khách — hay chỉ để chứa hàng mẫu, vật tư, thiết bị và tồn kho."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Phân loại phần diện tích đang bị thiếu"}]},{"type":"paragraph","content":[{"type":"text","text":"Nếu nhân sự không có chỗ làm hoặc cần thêm phòng họp, mở rộng văn phòng là bài toán đúng. Nếu bàn làm việc vẫn đủ nhưng lối đi, góc phòng và phòng họp đang chứa thùng hàng, vấn đề thực chất là thiếu không gian lưu trữ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"So tổng chi phí sử dụng, không chỉ đơn giá m²"}]},{"type":"paragraph","content":[{"type":"text","text":"Diện tích văn phòng thường kéo theo yêu cầu hoàn thiện, nội thất và kỳ vọng về vị trí/tiện ích khác với không gian chỉ dùng để lưu trữ. Vì vậy, so sánh nên dựa trên tổng chi phí để phục vụ đúng chức năng, không chỉ lấy giá thuê chia cho diện tích."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tần suất truy cập quyết định khoảng cách hợp lý"}]},{"type":"paragraph","content":[{"type":"text","text":"Đồ cần nhiều lần mỗi ngày nên ở gần đội ngũ. Hàng mẫu lấy vài lần mỗi tuần hoặc vật tư dự phòng có thể phù hợp với một điểm lưu trữ tách biệt hơn. Càng ít truy cập, doanh nghiệp càng có nhiều linh hoạt khi chọn nơi chứa."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tách kho cũng buộc quy trình rõ hơn"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Quy định ai được lấy/nhập hàng."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ghi vị trí từng nhóm tài sản."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lập lịch bổ sung vật tư về văn phòng."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kiểm kê định kỳ thay vì để đồ di chuyển tự phát."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Khi nào không nên tách kho"}]},{"type":"paragraph","content":[{"type":"text","text":"Nếu hàng cần truy cập liên tục, phụ thuộc vào thiết bị đặc thù tại văn phòng hoặc việc di chuyển qua lại gây gián đoạn lớn, tách kho có thể không hiệu quả. Mục tiêu không phải đưa mọi thứ ra xa, mà là giữ tại văn phòng đúng những gì giúp đội ngũ làm việc hàng ngày."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cách ra quyết định"}]},{"type":"paragraph","content":[{"type":"text","text":"Liệt kê 3 nhóm: phải ở văn phòng, có thể chuyển ra kho, và chưa chắc. Ước lượng diện tích từng nhóm và tần suất truy cập. Với nhóm có thể chuyển, hãy thử đối chiếu với một loại kho nhỏ trước. Một phương án tách kho tốt sẽ làm văn phòng gọn hơn mà không tạo thêm ma sát vận hành."}]}]}'::jsonb,'Thuê kho hay mở rộng văn phòng cho doanh nghiệp nhỏ? | NupsBox','So sánh logic thuê thêm văn phòng và tách riêng kho cho doanh nghiệp nhỏ dựa trên mục đích sử dụng, tần suất truy cập và chi phí không gian.'),
    ('kho-hay-mo-rong-van-phong','en','Small business: expand the office or separate storage?','If the real problem is samples, supplies and inventory taking over the workspace, a larger office may be an expensive solution to the wrong problem.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A crowded office does not automatically mean a business needs a larger office. Before expanding, ask what the missing area would actually be used for: desks, meeting rooms and client work — or simply samples, supplies, equipment and inventory."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Classify the missing space by purpose"}]},{"type":"paragraph","content":[{"type":"text","text":"If people lack desks or the team genuinely needs more meeting capacity, office expansion addresses the right problem. If the desks are fine but corridors and meeting rooms are full of cartons, the underlying shortage is storage."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Compare total occupancy cost, not only price per square metre"}]},{"type":"paragraph","content":[{"type":"text","text":"Office space often carries fit-out, furniture and location expectations that differ from space used only for storage. The comparison should therefore focus on the total cost of serving the required function, not a simple rent-per-square-metre figure."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Access frequency determines how close storage needs to be"}]},{"type":"paragraph","content":[{"type":"text","text":"Items used many times per day should remain close to the team. Samples retrieved a few times per week or backup supplies may work in a separate storage point. The lower the access frequency, the more flexibility the business has in where those items live."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Separate storage also forces clearer process"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define who can receive and retrieve items."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record where each asset group is stored."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Schedule replenishment back to the office."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use periodic counts instead of allowing ad-hoc movement."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When separate storage is not the answer"}]},{"type":"paragraph","content":[{"type":"text","text":"If inventory is accessed continuously, depends on specialist equipment at the office or frequent travel creates major disruption, separation may be inefficient. The goal is not to move everything away; it is to keep in the office what genuinely supports daily work."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A practical decision method"}]},{"type":"paragraph","content":[{"type":"text","text":"Create three groups: must stay in the office, can move to storage and uncertain. Estimate the area and access frequency of each. For the “can move” group, compare the requirement with a small storage unit first. A good separation plan makes the office clearer without adding operating friction."}]}]}'::jsonb,'Storage or a larger office for a small business? | NupsBox','Compare office expansion with separate storage based on purpose, access frequency and the total cost of space.'),
    ('quan-ly-hang-ton-cham-luan-chuyen','vi','Hàng tồn chậm luân chuyển: quản lý không gian trước khi mua thêm diện tích','Phân nhóm tồn kho theo mức độ quan trọng giúp giữ vị trí đẹp cho hàng tạo doanh thu, đồng thời nhìn rõ hàng chậm đang khóa vốn và chiếm chỗ.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Khi kho chật, phản xạ phổ biến là tìm thêm diện tích. Nhưng nếu phần lớn không gian đang bị chiếm bởi hàng chậm luân chuyển, mua thêm diện tích có thể chỉ kéo dài vấn đề. Trước tiên cần nhìn lại cấu trúc tồn kho: hàng nào thực sự cần vị trí tốt, hàng nào chỉ đang nằm lâu vì chưa có quyết định xử lý."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Dùng tư duy ABC để nhìn tồn kho theo mức độ quan trọng"}]},{"type":"paragraph","content":[{"type":"text","text":"Shopify mô tả ABC analysis như cách phân loại sản phẩm theo đóng góp doanh thu để ưu tiên nguồn lực quản lý. Điểm hữu ích cho thiết kế kho là không phải mọi SKU đều xứng đáng với vị trí dễ tiếp cận như nhau."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nhóm A: hàng quan trọng/bán tốt — cần kiểm soát chặt và dễ lấy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nhóm B: mức độ trung bình — vẫn cần sẵn có nhưng không phải vị trí đẹp nhất."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nhóm C: hàng đóng góp thấp hoặc chậm — cần xem lại lượng tồn và chi phí chiếm chỗ."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Không biến ABC thành một công thức cứng"}]},{"type":"paragraph","content":[{"type":"text","text":"Hàng mới, hàng theo mùa hoặc sản phẩm chiến lược có thể bị đánh giá sai nếu chỉ nhìn dữ liệu quá khứ. ABC là một góc nhìn để đặt câu hỏi, không phải quyết định tự động. Hãy kết hợp với biên lợi nhuận, mùa vụ, thời gian nhập lại và vai trò của SKU trong danh mục."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Bố trí kho theo tốc độ luân chuyển"}]},{"type":"paragraph","content":[{"type":"text","text":"Sau khi phân nhóm, hãy cho hàng nhanh vị trí dễ tiếp cận và giảm số lần phải di chuyển vật cản. Hàng chậm có thể vào vùng sâu hơn, tầng kệ cao hơn hoặc một khu riêng. Mục tiêu là để luồng hàng hàng ngày đi qua ít ma sát nhất."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Đo chi phí không gian của hàng chậm"}]},{"type":"paragraph","content":[{"type":"text","text":"Một SKU chậm bán không chỉ khóa tiền mua hàng; nó còn dùng vị trí kệ, diện tích sàn và thời gian kiểm kê. Khi xem xét tiếp tục giữ, giảm giá, bundle, trả nhà cung cấp hoặc thanh lý, hãy đưa chi phí không gian vào quyết định."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Khi nào kho ngoài có ý nghĩa"}]},{"type":"paragraph","content":[{"type":"text","text":"Kho ngoài có thể hữu ích nếu doanh nghiệp cần giữ hàng chậm vì lý do mùa vụ, hợp đồng hoặc chiến lược nhưng không muốn chúng chặn hoạt động tại điểm bán/văn phòng. Tuy nhiên, nếu hàng không còn lý do kinh doanh để giữ, chuyển nó sang một kho khác chỉ là di chuyển vấn đề."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Checklist rà soát mỗi tháng"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SKU nào không xuất trong kỳ?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SKU nào chiếm nhiều thể tích nhất?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SKU nào cần vị trí dễ lấy nhất?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nhóm hàng nào có thể giảm mức tồn?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Có hàng nào giữ vì thói quen thay vì nhu cầu?"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"NupsBox nên được xem như một công cụ trong chiến lược không gian, không phải lý do để giữ mọi tồn kho vô thời hạn. Phân loại hàng trước, rồi mới quyết định phần nào xứng đáng được dành không gian lưu trữ."}]}]}'::jsonb,'Cách quản lý hàng tồn chậm luân chuyển | NupsBox','Ứng dụng tư duy ABC để phân nhóm hàng tồn, bố trí vị trí kho và giảm diện tích bị chiếm bởi hàng chậm luân chuyển.'),
    ('quan-ly-hang-ton-cham-luan-chuyen','en','Slow-moving inventory: manage the space before buying more space','Inventory segmentation helps reserve the best positions for important products while exposing slow stock that ties up both cash and physical space.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When storage feels full, the natural reaction is to add more space. But if slow-moving inventory occupies much of the unit, more area can simply extend the problem. First examine the structure of the inventory: which products deserve premium access and which are staying because no decision has been made."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Use ABC thinking to prioritize inventory"}]},{"type":"paragraph","content":[{"type":"text","text":"Shopify describes ABC analysis as a way to classify products by revenue contribution so teams can prioritize management effort. For storage layout, the useful lesson is that not every SKU deserves the same quality of access."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A: important or high-performing stock — closely controlled and easy to reach."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B: mid-priority stock — available but not necessarily in the best positions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C: low-contribution or slow stock — review quantity and space cost."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Do not turn ABC into a rigid formula"}]},{"type":"paragraph","content":[{"type":"text","text":"New products, seasonal stock and strategic items can be misread if historical data is the only input. ABC is a lens for asking better questions, not an automatic disposal rule. Combine it with margin, seasonality, replenishment lead time and the product’s role in the range."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Lay out storage by movement velocity"}]},{"type":"paragraph","content":[{"type":"text","text":"Once stock is segmented, give fast movers the easiest positions and reduce the number of obstacles in their path. Slower products can move deeper into the unit, higher on shelving or into a separate zone. The goal is to remove friction from the daily flow."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Measure the space cost of slow stock"}]},{"type":"paragraph","content":[{"type":"text","text":"A slow SKU ties up more than purchase cash; it uses shelf positions, floor area and counting time. When deciding whether to keep, discount, bundle, return or liquidate stock, include the space cost in the decision."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When external storage can make sense"}]},{"type":"paragraph","content":[{"type":"text","text":"Separate storage can help when a business must retain slow inventory for seasonal, contractual or strategic reasons but does not want it blocking the shop or office. If the stock no longer has a business reason to exist, however, moving it to another unit merely relocates the problem."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Monthly review checklist"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Which SKUs had no outbound movement?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Which SKUs occupy the most volume?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Which products deserve the easiest access?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where can stock levels be reduced?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Are any items being kept by habit rather than need?"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"NupsBox should be treated as one tool in a space strategy, not a reason to keep every item forever. Segment inventory first, then decide which stock deserves storage capacity."}]}]}'::jsonb,'How to manage slow-moving inventory | NupsBox','Use ABC thinking to segment inventory, assign storage positions and reduce space consumed by slow-moving stock.'),
    ('kho-ca-nhan-chuyen-nha-sua-nha','vi','Kho cá nhân khi chuyển nhà, sửa nhà và cất đồ theo mùa: cách xếp để còn lấy được đồ','Một kho cá nhân tốt không chỉ chứa đủ. Nó cần phân lớp theo thời điểm cần lấy lại, bảo vệ đồ dễ hỏng và giữ một lối tiếp cận hợp lý.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Khi chuyển nhà hoặc sửa nhà, mục tiêu đầu tiên thường là “đưa đồ ra khỏi chỗ này càng nhanh càng tốt”. Nếu mọi thùng được đóng và xếp theo đúng thứ tự chúng xuất hiện, vài tuần sau bạn có thể phải dỡ nửa kho để tìm một giấy tờ, bộ dụng cụ hoặc đồ dùng cần gấp."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Chia theo thời điểm cần lấy lại"}]},{"type":"paragraph","content":[{"type":"text","text":"Trước khi đóng thùng, chia đồ thành ba lớp: cần trong vài ngày/tuần, có thể cần trong vài tháng và lưu dài hạn. Lớp cần sớm phải nằm gần lối vào. Lớp dài hạn có thể vào sâu hơn. Cách chia này quan trọng hơn việc xếp theo từng phòng trong nhà."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tạo một “hộp ưu tiên”"}]},{"type":"paragraph","content":[{"type":"text","text":"Hộp ưu tiên chứa giấy tờ, dụng cụ cơ bản, một số đồ điện tử/phụ kiện và những thứ bạn không muốn lục tìm trong hàng chục thùng. Đánh dấu khác màu hoặc mã riêng để nhận ra ngay."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Đồ nặng xuống dưới, đồ dễ vỡ tách khỏi tải trọng"}]},{"type":"paragraph","content":[{"type":"text","text":"Đừng dùng các hộp dễ biến dạng làm nền cho chồng thùng. Với đồ dễ vỡ, mục tiêu là tránh lực đè và tránh dịch chuyển. Chừa khoảng trống để lấy chúng ra mà không phải kéo hoặc nghiêng cả cụm hàng."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Đồ theo mùa nên được đóng theo chu kỳ sử dụng"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nhóm Tết/lễ hội."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nhóm du lịch hoặc dã ngoại."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Quần áo và chăn ga theo mùa."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Đồ trang trí và thiết bị ít dùng."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Nếu biết một nhóm sẽ cần lại cùng thời điểm, lưu chúng cùng khu vực và dùng nhãn rõ ràng. Điều này giảm số lần phải mở nhiều thùng chỉ để tìm một món."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Đừng lấp kín lối đi nếu thời gian lưu kéo dài"}]},{"type":"paragraph","content":[{"type":"text","text":"Với lưu ngắn vài ngày, xếp dày có thể chấp nhận được. Với vài tháng trở lên, khả năng cần lấy lại một món tăng lên. Một lối tiếp cận nhỏ nhưng có chủ đích thường đáng giá hơn việc nhồi thêm vài thùng vào khoảng trống."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trước khi chọn loại kho"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Đo món lớn nhất và đếm số thùng."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Xác định nhóm cần lấy sớm."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ước lượng đồ có thể xếp chồng an toàn."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Quyết định có cần lối đi xuyên kho hay không."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chụp ảnh hoặc lưu danh sách thùng trước khi đóng kho."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Khi liên hệ NupsBox, hãy mô tả bối cảnh sử dụng — chuyển nhà, sửa nhà hay lưu theo mùa — cùng số lượng thùng và đồ lớn. Những thông tin này giúp đối chiếu loại kho phù hợp tốt hơn nhiều so với chỉ nói “tôi cần một kho nhỏ”."}]}]}'::jsonb,'Cách dùng kho cá nhân khi chuyển hoặc sửa nhà | NupsBox','Hướng dẫn đóng, phân nhóm và sắp xếp kho cá nhân khi chuyển nhà, sửa nhà hoặc lưu đồ theo mùa để vẫn dễ lấy và kiểm soát.'),
    ('kho-ca-nhan-chuyen-nha-sua-nha','en','Personal storage for moving, renovation and seasonal rotation: pack so you can still retrieve things','Good personal storage is not only about fitting everything in. Layer belongings by retrieval timing, protect fragile items and preserve a deliberate access path.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"During a move or renovation, the first objective is often to get belongings out of the way as quickly as possible. If cartons are packed and stacked only in the order they appear, a few weeks later you may need to dismantle half the unit to find one document, tool kit or essential item."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Group by when you may need the item again"}]},{"type":"paragraph","content":[{"type":"text","text":"Before packing, create three layers: needed within days/weeks, possibly needed within months and long-term storage. Near-term items belong close to the entrance. Long-term items can go deeper. This retrieval-based grouping can matter more than organizing everything by room."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create one priority box"}]},{"type":"paragraph","content":[{"type":"text","text":"A priority box holds documents, basic tools, selected electronics/accessories and items you do not want to search for across dozens of cartons. Mark it with a distinctive color or code."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Heavy items low; fragile items away from load"}]},{"type":"paragraph","content":[{"type":"text","text":"Do not use deformable boxes as the base of a stack. Fragile belongings should avoid compression and should be retrievable without pulling or tilting a whole wall of cartons."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pack seasonal belongings by use cycle"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Holiday and celebration items."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Travel or outdoor equipment."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Seasonal clothes and bedding."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Decorations and infrequently used equipment."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"If a group will be needed at the same time, store it together and label it clearly. This avoids opening multiple cartons to find one item."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Do not eliminate every aisle for longer storage"}]},{"type":"paragraph","content":[{"type":"text","text":"Dense packing may be acceptable for a short hold of a few days. Over several months, the probability of retrieving something increases. A small deliberate access path is often more valuable than squeezing a few extra cartons into the gaps."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Before selecting a unit"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Measure the largest item and count cartons."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Identify near-term retrieval groups."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Estimate what can be stacked safely."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Decide whether you need a through-aisle."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Photograph or list cartons before the unit is closed."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"When contacting NupsBox, describe the use case — moving, renovation or seasonal storage — together with carton count and bulky items. Those inputs are far more useful for matching a unit than simply saying “I need a small storage space.”"}]}]}'::jsonb,'Using personal storage during moving or renovation | NupsBox','How to group, pack and arrange personal storage during a move, renovation or seasonal rotation while keeping belongings accessible.')
)
insert into public.blog_translations (
  blog_post_id, locale, title, excerpt, body, seo_title, seo_description
)
select
  u.id,
  t.locale,
  t.title,
  t.excerpt,
  t.body,
  t.seo_title,
  t.seo_description
from seed_translations t
join upserted u on u.slug = t.slug
on conflict (blog_post_id, locale) do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  body = excluded.body,
  seo_title = excluded.seo_title,
  seo_description = excluded.seo_description,
  updated_at = now();
